(function(){var d={"book": {"chapters": [{"container": "EXTENSION", "file": "vtm5e-0.5-new-blood-reference-guide-reference-guide.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - New Blood (V5 Starter Set): Reference Guide", "page": 1, "roots": ["#v9YJMxn5JvkAikUPUTo3djk"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-new-blood-reference-guide-welcome-to-the-world-of-darkness.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - New Blood (V5 Starter Set): Reference Guide - Welcome to the World of Darkness", "page": 2, "roots": ["#vp1hpm6eERv3bFQj44fd4WJ"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-new-blood-reference-guide-role-of-the-storyteller.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - New Blood (V5 Starter Set): Reference Guide - The Role of the Storyteller", "page": 4, "roots": ["#vkmsIBdbYAY4xpQWHIToTYQ", "#vtv4e2ncqvdMt2kZbcmSQ5N", "#vlCYUZfNkHFkbnoN53hmmWG", "#v3mrFdDl08trwGhoEbORdkN"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - New Blood (V5 Starter Set): Reference Guide - The Rules", "page": 7, "roots": ["#vISwG5SFQ4EkXVn8PzVOdrJ", "#vuMsNM8cGt1EOthfnq1ljTC", "#v8nFZjuk2T2pWeqCzyF8wn3", "#v2AcQ5CdcrtC5ZwZlSnImAk", "#vLwafg6cfXQxcNb0YzyrBcV", "#vnceWWHX27l44LST5nT7mzB", "#vtoXgNQ8n0gkjKVELt0Q5yF", "#vAFB4myKKR5sj2BQI2uelCr", "#vmyeHkRxiQlDZbaKPBKCRo5", "#vpHLxllQxGCc7i1KFCO7kDz", "#vti7zEGUf91sbGoOPgeQt3M", "#vL2Q38sgIJdj6UTRIJyY60v", "#v0brUAg1zgzzpgceGSxreWt"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-new-blood-reference-guide-characters-and-actions.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - New Blood (V5 Starter Set): Reference Guide - Appendix I: Characters and Actions", "page": 14, "roots": ["#vei3ZHargYbGuCA1iasCj8G", "#vNECRCW5UoqwcQIAVBonQEB"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-new-blood-reference-guide-glossary.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - New Blood (V5 Starter Set): Reference Guide - Appendix II: Glossary", "page": 15, "roots": ["#vACLWtava7cqGRepajgyaZB"]}], "entities": ["#v9YJMxn5JvkAikUPUTo3djk", "#vp1hpm6eERv3bFQj44fd4WJ", "#vkmsIBdbYAY4xpQWHIToTYQ", "#vtv4e2ncqvdMt2kZbcmSQ5N", "#vlCYUZfNkHFkbnoN53hmmWG", "#v3mrFdDl08trwGhoEbORdkN", "#vISwG5SFQ4EkXVn8PzVOdrJ", "#vuMsNM8cGt1EOthfnq1ljTC", "#v8nFZjuk2T2pWeqCzyF8wn3", "#v2AcQ5CdcrtC5ZwZlSnImAk", "#vLwafg6cfXQxcNb0YzyrBcV", "#vnceWWHX27l44LST5nT7mzB", "#vtoXgNQ8n0gkjKVELt0Q5yF", "#vAFB4myKKR5sj2BQI2uelCr", "#vmyeHkRxiQlDZbaKPBKCRo5", "#vpHLxllQxGCc7i1KFCO7kDz", "#vti7zEGUf91sbGoOPgeQt3M", "#vL2Q38sgIJdj6UTRIJyY60v", "#v0brUAg1zgzzpgceGSxreWt", "#vei3ZHargYbGuCA1iasCj8G", "#vNECRCW5UoqwcQIAVBonQEB", "#vACLWtava7cqGRepajgyaZB"], "id": "new-blood-reference-guide", "kind": "book", "label": "New Blood: Reference Guide"}, "entities": {"#v0brUAg1zgzzpgceGSxreWt": {"aliases": null, "book": "new-blood-reference-guide", "children": ["#vSvzMHj1pK9haafAFOftBt6", "#vQx7pg8kBv0ex3xc8AApgo2"], "choices": [], "desc": "Characters in **Vampire** constantly struggle to remain in contact with what once made them human. Their actions slowly degrade their soul, until they are taken over by the Beast. When that happens, the characters are lost: they become feral and uncontrollable, and will only act towards satisfying their Hunger or ensuring their own survival. There is no turning back.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#v0brUAg1zgzzpgceGSxreWt", "key": "The Human Being", "name": "The Human Being", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v2AcQ5CdcrtC5ZwZlSnImAk": {"aliases": null, "book": "new-blood-reference-guide", "children": ["#vne7FvweIoy4uJid4Up16w6"], "choices": [], "desc": "We will use Vampire dice to resolve any conflicts and to test the characters’ skills in extreme situations. Whenever a character is doing something unusual, particularly difficult, or under stressful circumstances, dice should be rolled. There are two types of dice: **Regular Dice** (black) and **Hunger Dice** (red).\n\nWhen rolling, look for . This represents a success. Blank faces are simply ignored. Regular dice have another icon, [Regular Die: Critical] , while Hunger dice have and , as well. Treat [Regular Die: Critical] and as a success and as a blank face.\n\n**USING STANDARD DICE** *If you don’t have access to Vampire dice, and want to use standard ten sided dice, use the following values for Regular Dice: results of 1-5 equal blank faces, 6-9 equal [Regular Die: Success] and 10 (or 0) equals [Regular Die: Critical] . For Hunger Dice, results of 2-5 equal blank faces, 6-9 equal , 10 (or 0) equals and 1 equals .*\n\n**ADVANCED DICE USE** *If you want to add an extra layer of complexity to your game, you can use the complete rules detailed here:*", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#v2AcQ5CdcrtC5ZwZlSnImAk", "key": "The Dice", "name": "The Dice", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v3mrFdDl08trwGhoEbORdkN": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "**Vampire** stories can discuss some **sensitive subjects**. Even though the world is dark and horrifying events are meant to take place in it, lines need to be drawn to protect the players’ sensibility. It is always a good idea to discuss beforehand with the players what they are comfortable with and what subjects they would rather not approach. If one player (including yourself) doesn’t feel good about dealing with a specific subject, no matter how insignificant it may seem to the rest, that subject should definitely be off the table. The player does not owe anyone an explanation for this. Please respect their needs and well-being. The experience, even if tense and challenging, should always be enjoyable for everybody.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-role-of-the-storyteller.ttrpg", "form": "DEF", "guidance": [], "id": "#v3mrFdDl08trwGhoEbORdkN", "key": "Sensitive Subjects", "name": "Sensitive Subjects", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v6oVzr8WGTIC6p0gjO1idt7": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "Every time a character takes any action that could increase their Hunger — such as waking up every night, or using some Discipline powers — they are Rousing the Blood, and they need to roll a Rouse Check.\n\nThe player rolls one regular die and, if the result is not a or [Regular Die: Success][Regular Die: Critical], they increase their Hunger by one.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#v6oVzr8WGTIC6p0gjO1idt7", "key": "Rouse Checks", "name": "Rouse Checks", "parent": "#vL2Q38sgIJdj6UTRIJyY60v", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v8nFZjuk2T2pWeqCzyF8wn3": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "Characters have two trackers to check their mental and physical well-being: Willpower and Health. These two Traits can never increase beyond their maximum level.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#v8nFZjuk2T2pWeqCzyF8wn3", "key": "Willpower and Health", "name": "Willpower and Health", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v93CM43WiAsSKPlwAQLE90W": {"aliases": null, "book": "new-blood-reference-guide", "children": ["#vxj9rWo1d1WyJB1jIFghssS"], "choices": [], "desc": "Using this method, you abstract a Conflict to one roll. The attacking side — generally the players — gathers a dice pool (using the **Attack** Action) and rolls against a Difficulty set by the Storyteller. If the attacking side beats that difficulty, their opponent is defeated.\n\nAfter resolving the roll, multiply the original difficulty by 2 and compare it against all the successes rolled. If the doubled Difficulty is greater than the number of successes, the attacking side takes an amount of damage based on the difference between those two values.\n\nOptionally, characters may take **Stains** (see below) instead of damage in these cases. This represents that the characters were particularly brutal during the struggle.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#v93CM43WiAsSKPlwAQLE90W", "key": "One-Roll Conflict", "name": "One-Roll Conflict", "parent": "#vpHLxllQxGCc7i1KFCO7kDz", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v9YJMxn5JvkAikUPUTo3djk": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "Reference *guide*\n\nWelcome to **Vampire**. This is the **Starter Set Reference Guide**. If you are reading this, you probably want to know more about the game, the rules, and the universe in which the stories take place.\n\nHere we’ll give you a quick glance over the rules and the universe of **Vampire**. If you want to learn more, we recommend you to acquire a copy of the **Vampire: The Masquerade 5th Edition** core rulebook.\n\nWe hope you enjoy your first experience with **Vampire**.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-reference-guide.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#v9YJMxn5JvkAikUPUTo3djk", "name": "Reference Guide"}], "id": "#vUtPzuKosBWhPKNMsJLLybK", "name": "Reference Guide Sidebar", "text": "Note: This book is intended to be used as a reference for rules of Vampire, and to allow players to create a continuation to the story presented in the Story Guide in this bundle. If you haven’t read the Story Guide, we recommend you to start there and read this afterwards.", "topics": []}], "id": "#v9YJMxn5JvkAikUPUTo3djk", "key": "Reference Guide", "name": "Reference Guide", "parent": null, "props": [{"items": [{"value": "**Welcome to the World of Darkness** will give you additional background information about the world in which the stories of **Vampire** take place.", "vk": "scalar"}, {"value": "**The Role of the Storyteller** provides advice and assistance to Storytellers who are new to this kind of gaming experience, or to veterans who are playing **Vampire** for the first time.", "vk": "scalar"}, {"value": "**The Rules** expands on what you found in the **Story Guide**, adding more complex systems that experienced or adventurous players can incorporate to their game.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vACLWtava7cqGRepajgyaZB": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-glossary.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#vACLWtava7cqGRepajgyaZB", "name": "Appendix II: Glossary"}], "id": "#v6dyYFoeH2ayniRed5Eo6eq", "name": "A NOTE ON PRINTING: You have express permission to print out any or all of", "text": "the documents contained in this bundle for personal use.", "topics": []}], "id": "#vACLWtava7cqGRepajgyaZB", "key": "Appendix II: Glossary", "name": "Appendix II: Glossary", "parent": null, "props": [{"name": "Aggravated Damage", "type": "STRING", "value": "Damage caused by sunlight, fire, supernatural means or excessive use of force, either physically (damage to Health) or psychologically (damage to Willpower).", "vk": "scalar"}, {"name": "Anarchs", "type": "STRING", "value": "A faction of the Camarilla that splintered in pursuit of their own freedom.", "vk": "scalar"}, {"name": "Attribute", "type": "STRING", "value": "The nine Traits that define the innate talents of a character.", "vk": "scalar"}, {"name": "Baron", "type": "STRING", "value": "The Anarch leader of a Domain.", "vk": "scalar"}, {"name": "Beast", "type": "STRING", "value": "The metaphysical incarnation of the vampiric curse living within the characters.", "vk": "scalar"}, {"name": "Bestial Failure", "type": "STRING", "value": "When a test is unsuccessful and at least one appears on the dice, the failure is epic, and carries tragic consequences.", "vk": "scalar"}, {"name": "Blood Surge", "type": "STRING", "value": "The ability to improve one Attribute by Rousing the Blood.", "vk": "scalar"}, {"name": "Brujah", "type": "STRING", "value": "One of the main seven Clans and one of the two most important Clans within the Anarchs. Also known as The Learned Clan or Rabble.", "vk": "scalar"}, {"name": "Caine", "type": "STRING", "value": "Rumored to be the first Kindred, cursed by God for murdering his brother.", "vk": "scalar"}, {"name": "Camarilla", "type": "STRING", "value": "A centuries-old organization of Kindred, dedicated to preserving the Traditions and the rule of the Elders.", "vk": "scalar"}, {"name": "Check", "type": "STRING", "value": "The system used to determine whether Hunger (Rouse Check) or Humanity (Remorse Check) decrease during or at the end of a session.", "vk": "scalar"}, {"name": "Childe", "type": "STRING", "value": "The progeny of a vampire. Relative to *sire*.", "vk": "scalar"}, {"name": "Choleric", "type": "STRING", "value": "The Resonance of victims who are angry, passionate or violent.", "vk": "scalar"}, {"name": "Clan", "type": "STRING", "value": "The thirteen different families of Kindred.", "vk": "scalar"}, {"name": "Conflict", "type": "STRING", "value": "A situation where two or more characters actively trying to damage each other either physically or mentally.", "vk": "scalar"}, {"name": "Contest", "type": "STRING", "value": "Any test that involves a player rolling against an active opponent.", "vk": "scalar"}, {"name": "Dice Pool", "type": "STRING", "value": "The amount of dice a character has to roll to overcome a test. Determined by the Storyteller by putting together two Traits, generally an Attribute and a Skill or Discipline.", "vk": "scalar"}, {"name": "Difficulty", "type": "STRING", "value": "The measure of how challenging a test is going to be, determined by the Storyteller based on the inherent difficulty of the action and any circumstances that can make it more or less complex.", "vk": "scalar"}, {"name": "Discipline", "type": "STRING", "value": "The supernatural powers that the vampiric curse bestows on Kindred.", "vk": "scalar"}, {"name": "Domain", "type": "STRING", "value": "A specific Kindred’s hunting ground, considered sacred by most Kindred, particularly among the Camarilla.", "vk": "scalar"}, {"name": "Elder", "type": "STRING", "value": "A Kindred of old age that holds the power within a specific Domain. Leaders of the Camarilla.", "vk": "scalar"}, {"name": "Embrace", "type": "STRING", "value": "The act of transforming a mortal into a vampire.", "vk": "scalar"}, {"name": "Gangrel", "type": "STRING", "value": "One of the main seven Clans and one of the two most important Clans within the Anarchs. Also known as The Clan of the Beast or Animals.", "vk": "scalar"}, {"name": "Health", "type": "STRING", "value": "The amount of physical damage a character can endure.", "vk": "scalar"}, {"name": "Humanity", "type": "STRING", "value": "The value that represents the degree of control the Beast has over a Kindred.", "vk": "scalar"}, {"name": "Hunger", "type": "STRING", "value": "The unquenchable thirst for blood that all Kindred suffer constantly.", "vk": "scalar"}, {"name": "Hunger Dice", "type": "STRING", "value": "The red dice used in **Vampire** to represent how the Beast gets stronger as Hunger increases.", "vk": "scalar"}, {"name": "Kindred", "type": "STRING", "value": "Vampire or vampires.", "vk": "scalar"}, {"name": "Malkavian", "type": "STRING", "value": "One of the main seven Clans. Also known as the Clan of the Moon or Oracles.", "vk": "scalar"}, {"name": "Margin", "type": "STRING", "value": "The difference between the number of icons rolled and the Difficulty determined by the Storyteller in a successful roll.", "vk": "scalar"}, {"name": "Masquerade", "type": "STRING", "value": "The Tradition that commands Kindred to refrain from revealing their true nature to the mortals at all costs.", "vk": "scalar"}, {"name": "Melancholy", "type": "STRING", "value": "The Resonance of victims who are sad, scared or depressed.", "vk": "scalar"}, {"name": "Messy Critical", "type": "STRING", "value": "When a critical is rolled, and there’s at least one icon on the Hunger Dice, the success exceeds expectations, but excessive force is used, with catastrophic consequences.", "vk": "scalar"}, {"name": "Nosferatu", "type": "STRING", "value": "One of the main seven Clans. Also known as the Clan of the Hidden or Sewer Rats.", "vk": "scalar"}, {"name": "Phlegmatic", "type": "STRING", "value": "The Resonance of victims who are lazy, apathetic or sentimental.", "vk": "scalar"}, {"name": "Remorse Check", "type": "STRING", "value": "The check players with Stains perform at the end of a session.", "vk": "scalar"}, {"name": "Resonance", "type": "STRING", "value": "The specific flavor and characteristics of a victim’s blood.", "vk": "scalar"}, {"name": "Rouse Check", "type": "STRING", "value": "The check a character rolls when any gift of the blood is used.", "vk": "scalar"}, {"name": "Sanguine", "type": "STRING", "value": "The Resonance of victims who are happy, horny, or over excited.", "vk": "scalar"}, {"name": "Second Inquisition", "type": "STRING", "value": "The collective name for the secret groups within different intelligence agencies around the world and the Society of Leopold.", "vk": "scalar"}, {"name": "Simple Test", "type": "STRING", "value": "Any test that involves a player rolling against an inanimate opponent.", "vk": "scalar"}, {"name": "Sire", "type": "STRING", "value": "A Kindred that Embraces a mortal. Relative to *childe*.", "vk": "scalar"}, {"name": "Skill", "type": "STRING", "value": "The Traits that define all the learned talents of a character.", "vk": "scalar"}, {"name": "Spc", "type": "STRING", "value": "Storyteller Player Character. Any character that appears in the game that is played by the Storyteller.", "vk": "scalar"}, {"name": "Stain", "type": "STRING", "value": "A cross in one of the empty slots on the Humanity Tracker, representing an act of depravity that has made an impact on the character’s soul.", "vk": "scalar"}, {"name": "Storyteller", "type": "STRING", "value": "The player that takes on the task of guiding the story.", "vk": "scalar"}, {"name": "Take Half", "type": "STRING", "value": "When the Storyteller decides to divide an SPC’s *dice pool* by two and use it as Difficulty in a Contest with a player to make the game flow better.", "vk": "scalar"}, {"name": "Test", "type": "STRING", "value": "The system used to resolve an action, putting together a dice pool and rolling dice.", "vk": "scalar"}, {"name": "The Society of Leopold", "type": "STRING", "value": "A secret group of witchhunters from the Vatican heavily invested in the Second Inquisition.", "vk": "scalar"}, {"name": "Toreador", "type": "STRING", "value": "One of the main seven Clans. Also known as the Clan of the Rose or the Divas.", "vk": "scalar"}, {"name": "Trait", "type": "STRING", "value": "Any value on the character sheet that can be tracked with dots.", "vk": "scalar"}, {"name": "Tremere", "type": "STRING", "value": "One of the main seven Clans. Also known as The Broken Clan or Warlocks.", "vk": "scalar"}, {"name": "Ventrue", "type": "STRING", "value": "One of the main seven Clans and the *de facto* leaders of the Camarilla. Also known as The Clan of Kings or Blue Bloods.", "vk": "scalar"}, {"name": "Willpower", "type": "STRING", "value": "The amount of psychological damage a character can endure, and their ability to overcome the odds under pressure.", "vk": "scalar"}, {"name": "World of Darkness", "type": "STRING", "value": "The universe in which **Vampire** stories take place.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vAFB4myKKR5sj2BQI2uelCr": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "When rolling the dice pool and succeeding, the player may get more than what the Difficulty set by the Storyteller requested. In those cases, the excess icons are called the **Margin**. This value can make the success more spectacular, or the action more effective.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vAFB4myKKR5sj2BQI2uelCr", "key": "Margin", "name": "Margin", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vE217DKIST14URxgfHO2FWG": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-characters-and-actions.ttrpg", "form": "DEF", "guidance": [], "id": "#vE217DKIST14URxgfHO2FWG", "key": "Remorse Table", "name": "Remorse Table", "parent": "#vNECRCW5UoqwcQIAVBonQEB", "props": [], "refs": [], "slot": null, "table": {"columns": ["Attack (Unarmed) / Bite", "2", "1", "1", "8", "6", "4", "7"], "rows": [["Attack (Firearms)", "4", "5", "6", "4", "5", "5", "4"], ["Insight", "6", "5", "9", "4", "2", "6", "5"], ["Intimidate", "5", "6", "5", "5", "4/6", "4", "6"], ["Investigate", "4", "6", "9", "5", "2", "9", "4"], ["Lockpick", "1", "2", "4", "5", "8", "2", "5"], ["Persuade", "9", "9", "4", "2", "2", "6", "6"], ["Sneak", "1", "2", "4", "5", "6", "3", "4"]]}, "type": "Table", "typeHash": "#vtm5Table000000000001"}, "#vH53XpbTPMIqroWGIGUIvWY": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "The same way characters can take violent physical action against each other, they can also engage in social competition, humiliating each other in public and ruining their enemies’ reputations. These sort of Conflicts are resolved the same way as in Combat, with a couple of minor differences. Dice pools are generally composed of Attributes like Manipulation, Charisma, Composure or Wits, combined with Skills like Persuasion, Etiquette or Leadership. Damage is not applied to the characters’ health, but to their Willpower.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vH53XpbTPMIqroWGIGUIvWY", "key": "Social Conflict", "name": "Social Conflict", "parent": "#vpHLxllQxGCc7i1KFCO7kDz", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vISwG5SFQ4EkXVn8PzVOdrJ": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "**Vampire** is a narrative game, where the story is always more important than the mechanics. However, there are situations where the skills of the characters are tested, and where conflicts need to be resolved in a fair and balanced way. That’s why there is a mechanical system in place. The mechanics allow players to quantify the talents of their characters, to customize their skills, and to resolve situations where arbitrary narrative could turn the gaming experience into a disappointing one.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vISwG5SFQ4EkXVn8PzVOdrJ", "key": "The Rules", "name": "The Rules", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vIYUhrYF6VwYYQboyB8TmCu": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "All Kindred can briefly raise any of their Attributes by using an inherent ability called **Blood Surge**. Any character can add one die to any roll, but they must also roll a Rouse Check. This increase only lasts for one roll and is for one specific Attribute, selected when activating this ability. Older Kindred, with more powerful blood, are able to increase their Attributes further.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vIYUhrYF6VwYYQboyB8TmCu", "key": "Blood Surge", "name": "Blood Surge", "parent": "#vL2Q38sgIJdj6UTRIJyY60v", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vL2Q38sgIJdj6UTRIJyY60v": {"aliases": null, "book": "new-blood-reference-guide", "children": ["#vdMNcZtYAN3g3xyO2rlBofC", "#vt6xvVBOxo6uTUUJH8O0Tw3", "#v6oVzr8WGTIC6p0gjO1idt7", "#vIYUhrYF6VwYYQboyB8TmCu", "#vwv9pIKrKiZ3XGDrKuUdCH3"], "choices": [], "desc": "Hunger represents the unquenchable thirst for blood that permeated the existence of Kindred. Every time a character does something that could increase their Hunger, like rising each night or using certain Discipline powers, they will roll a **Rouse Check** (see below).\n\nLowering Hunger is done by feeding. Drinking the Blood of animals will lower Hunger by one step, never completely taking it away. Feeding off mortals will lower Hunger further, but it won’t take the last dot of Hunger away. Fully draining a mortal — killing them —will lower Hunger completely. However, this will generate Stains (see **Stains**).", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vL2Q38sgIJdj6UTRIJyY60v", "key": "Hunger", "name": "Hunger", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vLwafg6cfXQxcNb0YzyrBcV": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "There are two types of situations in which the players or the Storyteller will have to roll dice in **Vampire**: tests and checks. Tests involve adding an Attribute and a Skill or a Discipline to build a *dice pool*, and rolling that number of dice, counting successes to surpass a difficulty set by the Storyteller. Most rolls in **Vampire** are tests.\n\nChecks involve rolling dice to determine whether the character’s Hunger (**Rouse Checks**) or Humanity (**Remorse Checks**) changes or not. Checks are not affected by Hunger dice, and cannot be rerolled by spending Willpower.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vLwafg6cfXQxcNb0YzyrBcV", "key": "Tests and Checks", "name": "Tests and Checks", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vNECRCW5UoqwcQIAVBonQEB": {"aliases": null, "book": "new-blood-reference-guide", "children": ["#vE217DKIST14URxgfHO2FWG"], "choices": [], "desc": "At the end of the session, every character with at least one Stain will perform a Remorse test, rolling as many dice as their remaining empty slots in the Humanity Tracker, not crossed as Stains. If there are no empty slots, the player will still roll one die. If there is at least one (or [Regular Die: Success][Regular Die: Critical]) icon among all the dice rolled, the character has been through enough shame and guilt and will take suffer no additional consequences. If there are no icons, this means that the Beast has won. The character has found a way of rationalizing their own bestial actions, and fails to see anything fundamentally wrong with them. In consequence, she loses one Humanity point for the next session. All Stains are removed after the Remorse test, regardless of the result.\n\nThis is a master table of all the characters and their **Action test** dice pools. Higher scores are marked **bold**. Very low scores (not even mentioned on the sheets) are in **red**.\n\nSkill Specialties allow adding 1 die in specific circumstances. They are factored in unless specified.\n\nDiscipline powers that add dice are always factored in. Rain can boost their intimidate with Discipline power **Eyes of the Beast**. **Blood Surge** allows adding **1 die**.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-characters-and-actions.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#vNECRCW5UoqwcQIAVBonQEB", "name": "Remorse"}], "id": "#vmNNklR97hgTvNEO1WKjvH3", "name": "Table: Characters and Actions Action Test Alexblakejaymarshrainsamterry Dice Pools", "text": "", "topics": []}], "id": "#vNECRCW5UoqwcQIAVBonQEB", "key": "Remorse", "name": "Remorse", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vPRIJklEuRTqBak0Xn2Sa0y": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "There are a few ways in which a Kindred can be completely destroyed. Exposure to sunlight or fire will burn them until they are reduced to ashes. Even though they are able to slowly regenerate lost limbs, no vampire can survive beheading. If their bodies take enough punishment, harm that would kill several mortals, they will also perish. A stake through the heart of a vampire will not kill them. However, it will paralyze them completely until the stake is removed. Garlic, crosses, running water, and other superstitions don’t affect Kindred.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vPRIJklEuRTqBak0Xn2Sa0y", "key": "Vulnerabilities", "name": "Vulnerabilities", "parent": "#vti7zEGUf91sbGoOPgeQt3M", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vQx7pg8kBv0ex3xc8AApgo2": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "Every time a character acts against their own moral code — committing crimes, betraying their friends, or otherwise getting involved in acts of bestial depravity — they will acquire a **Stain**. This is represented by crossing one of the empty slots in the Humanity Tracker. The higher the Humanity, the less empty slots a character will have. A character with Humanity 7 will have 3 empty slots, while a character with Humanity 4 will have 6 empty slots. This represents how a more degraded soul will have less moral qualms when taking an ethically questionable action.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vQx7pg8kBv0ex3xc8AApgo2", "key": "Stains", "name": "Stains", "parent": "#v0brUAg1zgzzpgceGSxreWt", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vSvzMHj1pK9haafAFOftBt6": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "The **Humanity** Tracker represents this struggle. Most characters start off with a Humanity value of 7 dots. As that value becomes lower, they become increasingly more monstrous, and their interactions suffer in consequence. Both mortals and animals instinctively react in a negative way towards characters with low Humanity. Conversely, characters who manage to keep their Humanity high will find it easier to interact with others, and to exert self control when tempted by the Blood.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vSvzMHj1pK9haafAFOftBt6", "key": "Humanity", "name": "Humanity", "parent": "#v0brUAg1zgzzpgceGSxreWt", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vUCNC9PxwoEKBeaNlD64gEa": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "Combat scenes can be exciting at first but, if they are allowed to last too long, they can easily become tedious. Storytellers are encouraged to keep Combat scenes limited to a maximum of three turns. After this time, the Storyteller should evaluate who is winning, and find a narrative way to end the situation. This can be easily sorted out by making enemies run away, surrender, or fall unconscious. If the player characters are the ones losing, the Storyteller can politely make them see that their cause is lost, and that it’s time to consider a less direct approach.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vUCNC9PxwoEKBeaNlD64gEa", "key": "Extended Combat", "name": "Extended Combat", "parent": "#vpHLxllQxGCc7i1KFCO7kDz", "props": [{"name": "Close Combat", "type": "STRING", "value": "Two characters involved in a brawl or a close combat altercation will roll dice pools composed of their Strength Attribute, and the appropriate Skill (Brawl or Melee, depending if the combatants are armed or not). Any Margin (i.e. successes exceeding those of the opposing side) will add to the Damage the contest’s winning side deals to the losing side. Damage is factored by adding this Margin to applicable damage modifiers. Superficial Damage is always halved (rounding up) before applying it to the Health track. Any attacks that inflict Aggravated Damage (see below) are not halved.", "vk": "scalar"}, {"name": "Firearms and Ranged Weapons", "type": "STRING", "value": "Conflicts based on firearms or any other types of ranged weapons are resolved the same way as Close Combat Conflicts, but instead of using a dice pool composed of the Strength Attribute and the Brawl or Melee Skill, the characters will use the Composure Attribute and the Firearms Skill. If only one of the characters is shooting, the other character will roll as if they were dodging, probably with a negative Modifier.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vZ82wUqZuKFkaMaE6QgH1mA": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "For this scenario, to make the game easier to learn for all the players, we’ve added some pre-generated **Actions** to the character sheets. These **Actions** are short-hand combinations of Attributes and Skills that often come up. As all of you start feeling comfortable with the mechanics of **Vampire**, you can stop using **Actions** and just call for an **Attribute + Skill** combination as you see fit.\n\nNote that some of the characters’ supernatural powers will increase the *dice pool* for certain **Actions**. These values are already factored into the **Action** if the power is active, but will have to be considered when building your own *dice pools.*", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vZ82wUqZuKFkaMaE6QgH1mA", "key": "Actions", "name": "Actions", "parent": "#vpHLxllQxGCc7i1KFCO7kDz", "props": [{"name": "Attack (Unarmed)", "type": "STRING", "value": "Strength + Brawl", "vk": "scalar"}, {"name": "Attack (Firearms)", "type": "STRING", "value": "Composure + Firearms", "vk": "scalar"}, {"name": "Bite", "type": "STRING", "value": "Strength + Brawl", "vk": "scalar"}, {"name": "Investigate", "type": "STRING", "value": "Intelligence + Investigation", "vk": "scalar"}, {"name": "Lockpick", "type": "STRING", "value": "Dexterity + Larceny (Lockpick)", "vk": "scalar"}, {"name": "Persuade", "type": "STRING", "value": "Charisma or Manipulation + Persuasion", "vk": "scalar"}, {"name": "Intimidate", "type": "STRING", "value": "Charisma or Manipulation + Intimidation", "vk": "scalar"}, {"name": "Insight", "type": "STRING", "value": "Intelligence + Insight", "vk": "scalar"}, {"name": "Sneak", "type": "STRING", "value": "Dexterity + Stealth", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vdMNcZtYAN3g3xyO2rlBofC": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "Every time a character has to roll a test (as opposed to a check, such as a Rouse Check), the player builds their dice pool starting with as many Hunger dice as they have Hunger, up to the actual limit of the dice pool, filling in the rest with Regular dice.\n\n*Emily is playing Rain and wishes to use her Lockpicking action. Rain has 8 dice for that. Currently, Rain has 3 Hunger. When building the dice pool, she grabs 3 Hunger dice representing her Hunger, plus 5 Regular dice to complete the pool of 8. If she had had only 2 dice in total, she would have rolled 2 Hunger dice and 6 Regular dice.*\n\nHunger dice cannot be re-rolled, and they add some special icons that can bring unexpected negative consequences to any dice roll. If it is your first time running this game, we recommend that you ignore the special icons on the dice.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vdMNcZtYAN3g3xyO2rlBofC", "key": "Hunger Dice", "name": "Hunger Dice", "parent": "#vL2Q38sgIJdj6UTRIJyY60v", "props": [{"items": [{"value": "**EXAMPLE:**", "vk": "scalar"}], "name": "Examples", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vei3ZHargYbGuCA1iasCj8G": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "When a character has no free slots, and receives a new Stain, they are overcome by the monstrosity of their own actions. They will become **Impaired** for the rest of the session. This means that they will subtract 2 dice from all their dice pools. In addition, any Stains acquired over this limit will be taken as Aggravated Willpower Damage. The player can, at any point, decide to rationalize their horrifying actions as natural, lose one point of Humanity, and remove all Stains.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-characters-and-actions.ttrpg", "form": "DEF", "guidance": [], "id": "#vei3ZHargYbGuCA1iasCj8G", "key": "Appendix I: Characters and Actions", "name": "Appendix I: Characters and Actions", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vic2EmhIY4n3O0GhwEqmfTq": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "There are two kinds of damage: **Superficial Damage** and **Aggravated Damage.** Wounds produced by fire, sunlight or some supernatural attacks are Aggravated for Kindred. Mortals take Aggravated Damage not only from fire and some supernatural attacks, but also of attacks using slashing or piercing weapons (including guns)\n\nKindred can easily heal Superficial Damage just by using their Blood. The character can just **Rouse the Blood**, make a **Rouse Check**, and a point of Superficial Damage will be healed. This can be done once per turn. Aggravated Damage, however, takes days or even weeks to be fully healed. Any amount of regular damage that surpasses the character’s Health is considered Aggravated Damage. Similarly, any amputated limb or body part involves taking Aggravated Damage.\n\nOn the character sheet, Health is reduced by crossing the empty Health dots with a single line. Aggravated Damage is represented by a cross. When a character has their Health Tracker full of crosses, the character is dead.\n\nAggravated Damage can also be applied to Willpower, when circumstances or the actions of others push the character over the edge, emotionally or psychologically, Aggravated Willpower Damage is received. At the beginning of each session, each character heals an amount of **Superficial Willpower Damage** equal to their **Composure** or their **Resolve** (whichever is higher.) Characters also can heal one point of **Superficial Willpower Damage** once per session if the Storyteller judges they are actively trying to further their **Desire**. Finally, a character can heal one point of **Aggravated Willpower Damage** if the Storyteller considers they have been actively trying to satisfy their **Ambition**.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vic2EmhIY4n3O0GhwEqmfTq", "key": "Superficial and Aggravated Damage", "name": "Superficial and Aggravated Damage", "parent": "#vti7zEGUf91sbGoOPgeQt3M", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vkmsIBdbYAY4xpQWHIToTYQ": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "channels to communicate with one another. But mortals are paranoid by nature, and look for enemies everywhere. It was only a matter of time before Kindred were discovered by governments and intelligence agencies.\n\nIn 2001, in the wake of the events that led to the War on Terror, intelligence agencies across the globe started reinforcing surveillance, both online and offline. By mere accident, they discovered a hidden network of secret societies populated by monsters of legend. Joining forces with the Society of Leopold — a mystical group of witch hunters based in the Vatican — agencies like the CIA and MI6 took the job the Inquisition left unfinished in the Middle Ages. This was how mortals started hunting Kindred again.\n\nDuring the Second Inquisition’s first decade, they achieved impressive results. The online presence of Kindred was completely removed and the undead population of entire cities was exterminated. The creatures of the night were forced to take desperate measures. They retreated from the virtual world. Fear and paranoia became the rule among them.\n\nYour task is to flesh out everything and everybody that is not the player characters. It means knowing which events will happen, when they will happen, and who will be involved in those events. At least, that’s how the players often perceive it. The truth is that most of that task is based on improvisation, although good, solid preparation is advisable. You’re your players’ guide and facilitator. All of you tell a story together. No matter how close or far away it is from the plan you had in mind at first, the story always belongs to the group.\n\nThe world is populated by all sorts of characters. You have the task of portraying them. These are called **Storyteller Player Characters (SPCs)**. Some Storytellers tackle the task of playing the SPCs by putting on accents, changing their body language, and trying to make each and every one of them sound and feel different. Others take on a more narrative approach, explaining the particularities of each SPC, rather than acting them out. Both approaches work. Keep in mind that the Storyteller is also a player, so you should choose whatever approach makes you feel more comfortable. The idea is for you to enjoy the game as much as the rest of the group.\n\nA good Storyteller should always have clear information about the SPCs. You don’t need to write the biography of every SPC in the game in advance. Just a couple of details will help you flesh out the world, and give a sense of its depth and richness. For example: the woman waiting at a bus station bites her nails, and has a band on her wrist, identifying her as an organ donor. The shady drug dealer in the nightclub has a picture of his little sister in his wallet. A tattoo of a snake can be seen creeping up the neck of the nun offering shelter to the players when the morning comes.\n\nEveryone should feel they are the protagonist of the story at one point or another. If a player has been quiet for most of the time, or is too shy to participate in group decisions, be there to help. Give them their fair share of the spotlight. Maybe this involves separating their character from the group for a short while, or presenting a challenge that only that character can surpass. Don’t play favorites, though. The point is for everyone to have fun.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-role-of-the-storyteller.ttrpg", "form": "DEF", "guidance": [], "id": "#vkmsIBdbYAY4xpQWHIToTYQ", "key": "The Role of the Storyteller", "name": "The Role of the Storyteller", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vlCYUZfNkHFkbnoN53hmmWG": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "Roleplaying games are not about winning or losing. With this in mind, the notion of the Storyteller being an adversary to the players becomes absurd. You are allies in the quest for telling a fascinating story, where the players are the protagonists. Sometimes, this means twisting the world a little bit to promote epic situations, where heroes survive against all odds, or when unfathomable tragedy strikes them.\n\nStories in **Vampire** are meant to be exceptional, never mundane. As such, it is perfectly valid to skip scenes where nothing significant happens. Players will get bored quickly if they spend two hours of a session discussing how they follow the same routine day after day, hoping something special will happen in their lives. Help the players by presenting them with situations where their characters are shown to be exceptional — for good or for bad — and where their moral choices matter.\n\nStories derail. Players have creative minds, and their curiosity will lead them to explore alleys that you never considered describing in depth. They will insist on getting close to SPCs that were not fleshed out. They will ignore the main point of the story, and establish a set of ambitions for their characters that will lead them to unexpected places. Dealing with this can be the bane of many Storytellers.\n\nWhen you feel the need to herd the players back into the path that was prepared in advance, a question should arise before taking any step: is it really necessary? Maybe what the players are proposing is, after all, much more interesting and fascinating.\n\nIf there is no option than pushing the players back into the path that you prepared in advance, there is only one way of doing it: gently. You have to be flexible and understanding, and possess the ability to improvise ways in which the story can follow its course, without micromanaging them.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-role-of-the-storyteller.ttrpg", "form": "DEF", "guidance": [], "id": "#vlCYUZfNkHFkbnoN53hmmWG", "key": "An Ally to the Players", "name": "An Ally to the Players", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vmyeHkRxiQlDZbaKPBKCRo5": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "In many situations, the actions of the characters will be opposed to the actions of others. Any scenario where two characters compete is called a Contest.\n\nContests are very similar to Simple Tests, but there is one aspect that is different: the Difficulty. These are the steps to follow in a Contest:\n\nPlayers can start Contests against other players. The Storyteller still determines the dice pools for both players. When the Contest happens between a player and an SPC, the Storyteller may determine the dice pool for the SPC, and divide it in half, making it a fixed Difficulty for the player. This is called **Taking Half,** and it can make the game flow faster, avoiding unnecessary dice rolling.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vmyeHkRxiQlDZbaKPBKCRo5", "key": "Contests", "name": "Contests", "parent": null, "props": [{"items": [{"value": "The active player describes what they want to do, and how they want to do it.", "vk": "scalar"}, {"value": "The Storyteller determines the dice pool the player will use, by specifying which Attribute and Skill or Discipline have to be put together.", "vk": "scalar"}, {"value": "The Storyteller then determines the dice pool the opposing character will use. Keep in mind that characters involved in a Contest don’t have to necessarily use the same Traits. A character may be trying to run out of a building, while the opposing character may be trying to hack the security terminal to lock the doors.", "vk": "scalar"}, {"value": "Both characters roll their dice pools. Whoever gets more will win the contest.[Regular Die: Success]", "vk": "scalar"}, {"value": "The difference between the rolled by both characters is the Margin.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vnceWWHX27l44LST5nT7mzB": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "These tests represent the majority of the dice rolls in an average game of **Vampire**. When a character attempts to do something that would require rolling dice, the following steps are followed:\n\nThe Difficulty set by the Storyteller should generally be between 1 and 5, using higher difficulties for extreme situations. Keep in mind that most actions will have a difficulty of 2 or 3. Except when noted, avoid higher numbers for this scenario.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vnceWWHX27l44LST5nT7mzB", "key": "Simple Tests", "name": "Simple Tests", "parent": null, "props": [{"items": [{"value": "The player describes to the Storyteller what they want to achieve, and what strategy they are using.", "vk": "scalar"}, {"value": "The Storyteller decides which two Traits are going to be used. The combination of those two traits is called a *dice pool*.", "vk": "scalar"}, {"value": "The Storyteller determines a Difficulty and chooses whether to keep it secret or not.", "vk": "scalar"}, {"value": "The player rolls all the dice in their dice pool together. Any dice that shows a , [Regular Die: Success][Regular Die: Critical] or icon is a success.", "vk": "scalar"}, {"value": "If the number of these icons is equal or higher than the Difficulty set by the Storyteller, the player has succeeded.", "vk": "scalar"}, {"value": "If the number of these icons is lower than the Difficulty, the player has failed.", "vk": "scalar"}, {"value": "If none of these icons are rolled, the player has not only failed, but has done so in a catastrophic way, and there will be unexpected consequences.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vne7FvweIoy4uJid4Up16w6": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vne7FvweIoy4uJid4Up16w6", "key": "The Dice Table", "name": "The Dice Table", "parent": "#v2AcQ5CdcrtC5ZwZlSnImAk", "props": [], "refs": [], "slot": null, "table": {"columns": ["■CRITICAL ■", "- Regular Dice. This represents an"], "rows": [["exceptional success. When counting the number", ""], ["of successes, every two [Regular Die: Critical] count as 4 successes,", ""], ["instead of 2. In case of individual or odd [Regular Die: Critical]", ""], ["showing up, they count as one success only.", ""], ["■MESSY ■", "- Hunger Dice. This works identically"], ["as [Regular Die: Critical], with one important difference. In", ""], ["circumstances in which we have a pair of", ""], ["or one and one the roll becomes a Messy", ""], ["Critical. This means the character has succeeded", ""], ["beyond measure, getting carried away by their", ""], ["own Beast, and a negative consequence will arise.", ""], ["■SKULL ■", "- Hunger Dice. This is the opposite of"], ["a [Regular Die: Critical]. Whenever the total roll was not successful,", ""], ["and this symbol appears, the character has not", ""], ["only failed her action, but the Beast inside her has", ""], ["been somehow angered and she loses control in", ""], ["an unpredictable and destructive manner. This is", ""], ["called a Bestial Failure", ""]]}, "type": "Table", "typeHash": "#vtm5Table000000000001"}, "#vp1hpm6eERv3bFQj44fd4WJ": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "Legends and myths talk of monsters and beasts. Cautionary tales warn us of the dangers of the night. Stories turned into books, and then into films and hit TV shows. They are there to entertain and educate us. In the World of Darkness, the creatures from those legends live among us, walking the same streets and listening to the same podcasts.\n\nIn **Vampire**, the players take on the role of vampires, trying to find their place in a complex tapestry of ancient politics, personal vendettas, and the ever frustrating struggle to remain human.\n\nKINDRED Vampires in this game refer to themselves as **Kindred**. They are similar and different to vampires as portrayed in other media. For example, Kindred can be killed by the sun and by fire, but stakes merely paralyze them. Except for anomalous cases, none of the classic superstitions affect them: garlic, crossing running water, entering homes uninvited, and so on.\n\nMany Kindred believe that they descend from the biblical murderer Caine, who was cursed and turned into the first of them. Their society is built around how far they are removed from this mythical figure (their **Generation**), how old and powerful they are, and what **Clan** they belong to. Kindred may join factions, such as the **Anarchs** and **Camarilla**. All exist in fear of the dreaded **Second Inquisition.**\n\nKINDRED CLANS Kindred are divided into clans. Each one holds a different aspect of the Beast that was imposed upon the original Kindred. Clans are transmitted by blood from the **sire** (the progenitor) to the **childe** (her progeny). The following are featured in this scenario:\n\nThe **Brujah**, usually known as Rabble, are philosophers and rebels by nature. Their physical prowess only competes with their passion for humanity and all that it has to offer. They are one of the core Clans of the Anarchs. Their Beast represents itself as uncontrollable bursts of blind rage, rendering pointless their best arguments for peace and justice.\n\nThe **Gangrel** live in communion with nature. Although they are generally regarded as loners, with no interest in Kindred politics and society, they often gather in packs, like wolves, creating their own communities. They are the other central Clan of the Anarchs. The nature of their Beast mocks them, punishing them with animal traits — both physical and psychological — whenever they lose control.\n\nMany have lost their minds trying to understand the psyche of the **Malkavian**. Gifted with unique insight on the cryptic codes that rule the world around them. If the Oracles are often cryptic, that’s only because it is impossible to coherently express the magnitude of their vision. They are generally underestimated but, behind their extravagant ways, there is always the spark of genius.\n\nThe **Nosferatu** wear their Beasts in their lapels, on their faces, and written all over their bodies. Their curse may seem like one of the cruelest: upon receiving the **Embrace** — the act of transforming a mortal into Kindred — they suffer the most horrific metamorphosis, turning them into monsters of nightmare. Even though they display their monstrosity on the outside, the clan often gives fruit to the most humane and psychologically complex Kindred.\n\nLovers of humanity, beauty, and splendor, the **Toreador** are regarded as the most sensual of Kindred. Their pursuit of aesthetic perfection has drawn them for centuries towards the arts. They gather in art galleries and theaters to play their social games, and become involved in the lives of mortals like no other Clan. Their aesthetic sensibility is so acute that they have grown vulnerable to environments that don’t agree with their taste, suffering from anxiety and melancholy whenever they are not surrounded by beauty\n\nA thousand years ago, a powerful magician captured a vampire and performed a terrible ritual on her. The magician was obsessed with eternal life, and got the curse of Caine in exchange. Since then, the descendants of **Tremere** have been accumulating knowledge and bowing to a rigid hierarchy. However, since the Second Inquisition laid waste to their Chantry in Vienna, their whole lineage has grown weak and disunited. Nowadays, the Tremere sell their services as mercenaries, and try to understand how to live with their newfound freedom.\n\nTraditional leaders of the Camarilla, the **Ventrue** — or the Blue Bloods, as they are often called — exude majesty, power and privilege. They are educated on the idea that they are born to rule, and everybody else needs to obey them. The Ventrue have rarefied tastes when it comes to blood, and can only feed on specific types of people. The nature of this exquisite palate varies from one Ventrue to the next — some can only feed on middle-aged men, while others won’t taste any blood that doesn’t come from convicted felons.\n\nTHE CAMARILLA During the Dark Ages, when the Inquisition appeared, Kindred were not ready, and many of them paid the price. The survivors gathered and established a series of commandments that would ensure their survival. The Elders decided that they would be in power, and their word would be the law. This was the origin of the Camarilla, the largest vampire community ever known.\n\nTHE ANARCHS The Anarchs splintered from the Camarilla. With whole cities under their control, the Anarchs now stand as a force to be reckoned with. Government is loose, and it changes wildly from place to place, but the principle remains: age is not the measure of leadership. Some are eager to build a fair society, while others are hungry for power. All of them are the Anarchs, more an identity than a real group.\n\n**THE SECOND INQUISITION** With the explosion of the Age of Information, hiding has become harder than ever. At first, Kindred tried to use all the new technologies to their own advantage. They created secret networks in the dark web, and established", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-welcome-to-the-world-of-darkness.ttrpg", "form": "DEF", "guidance": [], "id": "#vp1hpm6eERv3bFQj44fd4WJ", "key": "Welcome to the World of Darkness", "name": "Welcome to the World of Darkness", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vpHLxllQxGCc7i1KFCO7kDz": {"aliases": null, "book": "new-blood-reference-guide", "children": ["#v93CM43WiAsSKPlwAQLE90W", "#vUCNC9PxwoEKBeaNlD64gEa", "#vH53XpbTPMIqroWGIGUIvWY", "#vZ82wUqZuKFkaMaE6QgH1mA"], "choices": [], "desc": "The World of Darkness is a dangerous place. Violent situations arise constantly. The physical and mental health of the characters is always at risk. When two or more characters oppose violently (either by using physical violence or by trying to humiliate each other in a social environment), **Conflict** arises.\n\nConflicts are resolved by using the rules for Contests. The opposing parties roll the dice pools determined by the Storyteller, and whoever gets more [Regular Die: Success] wins the Conflict. In this kind of roll, however, the Margin determines the degree of success and the amount of Health or Willpower the unsuccessful party loses in the process.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vpHLxllQxGCc7i1KFCO7kDz", "key": "Conflicts", "name": "Conflicts", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vt6xvVBOxo6uTUUJH8O0Tw3": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "Not all blood tastes the same. The true connoisseur will know that, and will also know that the emotional state of the victim will definitely have an impact on the flavour and the properties of the blood consumed.\n\nIn **Vampire**, this is contemplated in the form of Resonances. These represent the basic ways in which blood can be unique to each victim.\n\nThere are four Resonances, taken from the traditional theory of the four humours. Every blood has a Resonance, but the intensity of that Resonance is variable. When Kindred feed off a victim who has a very intense Resonance, they can acquire temporary or even permanent powers and advantages.\n\nFor starters, an intense Resonance will give the character an additional die for every Discipline roll involving any of the Disciplines connected with that Resonance. On top of that, and only in extremely exceptional cases where the Resonance is just overwhelming, some additional and unexpected advantages can be acquired.\n\nHere are the four Resonances:\n\nProvides bonuses to **Fortitude** and **Obfuscate**.\n\nProvides bonuses to **Presence** and **Blood Sorcery**.\n\nDrinking blood from animals also provides a Resonance, which will give a bonus to Discipline rolls for **Animalism** and **Protean**.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vt6xvVBOxo6uTUUJH8O0Tw3", "key": "Resonances", "name": "Resonances", "parent": "#vL2Q38sgIJdj6UTRIJyY60v", "props": [{"name": "Choleric", "type": "STRING", "value": "Angry, violent, passionate. Provides bonuses to **Celerity** and **Potence**.", "vk": "scalar"}, {"name": "Melancholy", "type": "STRING", "value": "Sad, scared, depressed.", "vk": "scalar"}, {"name": "Phlegmatic", "type": "STRING", "value": "Lazy, apathetic, sentimental. Provides bonuses to **Auspex** and **Dominate**.", "vk": "scalar"}, {"name": "Sanguine", "type": "STRING", "value": "Horny, happy, enthusiastic.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vti7zEGUf91sbGoOPgeQt3M": {"aliases": null, "book": "new-blood-reference-guide", "children": ["#vPRIJklEuRTqBak0Xn2Sa0y", "#vic2EmhIY4n3O0GhwEqmfTq"], "choices": [], "desc": "Kindred are monsters by nature, dominated by their Hunger, struggling to hold on to whatever Humanity they’ve got left. The blood changes them and makes them different from mortals in many ways.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vti7zEGUf91sbGoOPgeQt3M", "key": "The Monster", "name": "The Monster", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vtoXgNQ8n0gkjKVELt0Q5yF": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "Simple Tests can be modified by different factors. Getting assistance from a colleague, or relying on the right type of equipment will help the character, while being under unnecessary pressure or lacking the right tools will be detrimental to the completion of the task.\n\nIf the Modifiers reduce Difficulty set by the Storyteller to 0 or less, the Simple Test will be considered an automatic success, as the action doesn’t warrant rolling the dice anymore.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vtoXgNQ8n0gkjKVELt0Q5yF", "key": "Modifiers", "name": "Modifiers", "parent": null, "props": [{"name": "Teamwork", "type": "STRING", "value": "If any other character wants to assist another player facing a Simple Test, they can only do so if they have at least one dot in the Skill involved in the dice pool. If the dice pool doesn’t include a Skill, any character can collaborate. Their assistance will be reflected by adding one die to the dice pool.", "vk": "scalar"}, {"name": "Equipment", "type": "STRING", "value": "Some tasks require the use of specific equipment. The Storyteller may choose to increase the Difficulty by 1 point if the character doesn’t have the right equipment, or even to decide that the action cannot be performed. It may also happen that the character has access to special equipment of a better quality. This would reduce the Difficulty by 1 point.", "vk": "scalar"}, {"name": "Circumstantial Modifiers", "type": "STRING", "value": "An alarm beeping, a swarm of insects, heavy rain or even obsessive thoughts can make any task significantly more difficult. The Storyteller may choose to increase the Difficulty by 1 or 2 points — in particularly stressful situations — if the circumstances warrant it. This can also be applied the other way around, when the circumstances are favorable to the character, making their task easier. In that case, the Storyteller may decrease the Difficulty by 1 or 2 points.", "vk": "scalar"}, {"name": "Willpower", "type": "STRING", "value": "A player may choose to spend a dot of Willpower in any Test to re-roll up to three of their Regular (not Hunger) dice, if they don’t like the result on them. However, the new result must be accepted, even if it’s worse than the original one. Willpower is also used as a “health” track in social conflict", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vtv4e2ncqvdMt2kZbcmSQ5N": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "The World of Darkness is mostly like the world around us, but shadows are longer, sorrow is deeper, and danger lies everywhere. Crime is always on the rise, and all politicians are corrupt. To create the right atmosphere, the darkness should always be heightened. Every character who appears in the story has the potential of hiding a terrible secret and, those who don’t, serve a much more sinister dramatic purpose. Innocence acts as a cautionary tale, and a way of injecting horror into the story.\n\nThe main themes of Vampire are personal horror and political horror. These concepts pull characters and stories in two opposite directions. Personal horror talks about the internal lives of the characters. Their connections to the world of the mortals. Their emotional world. There are many stories that can be told about guilt, shame, desire, and the dehumanizing act of drinking other people’s blood to survive. Political horror refers to the world of Kindred, with their internal struggles, their fights for power and dominance, and the games of social and political control they play upon each other. Conflict between Kindred almost always leaves behind a trail of death and tragedy.\n\n*Personal Horror: Mara goes out hunting. She finds a lonely man in the last car of the train. He fiddles nervously with his phone. Mara approaches him and, without much ceremony, starts feeding off him. There’s something special about his blood. It is just delicious. She loses control, and drinks too much. The man is dead. While Mara tries to come to terms with what she has done, the man’s phone beeps. She fearfully reads the message: “It’s a boy! Congratulations, Frank! You are a father!”*\n\n*Political Horror: Jake learns that one of his friends, Nathan, is about to defect to the Camarilla. Concerned, Jake bring this information to the local Baron, who decides that Nathan needs to be destroyed to protect the community. A massive manhunt is organized. The traitor is found and beheaded. Jake is left with the task of tying loose ends. Horrified, he discovers that Nathan had revealed his nature to his family and that they are about to share his secrets with an agent of the Second Inquisition. Murdering them appears to be the only viable option for Jake.*\n\nEach **Vampire** story can feature elements from both worlds, or focus on either of them. Political horror can transition into personal horror and vice versa. It’s just a matter of changing the focus and the scale of the story.\n\nExternal aids like music, images or even costumes and props can help you create the perfect atmosphere for a **Vampire** game. As long as all the players — including you — feel comfortable with the elements brought to the table, anything that can make the story more believable and fascinating is welcome. Having at hand a laptop with a collection of music and sound effects can be incredibly effective, if used sparsely and with taste. The way in which the room is set and lit can also have a definite impact on the experience. Dimming the lights can bring a more intimate and mysterious atmosphere, keeping in mind that players should be able to comfortably read their character sheets.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-role-of-the-storyteller.ttrpg", "form": "DEF", "guidance": [], "id": "#vtv4e2ncqvdMt2kZbcmSQ5N", "key": "Setting the Atmosphere", "name": "Setting the Atmosphere", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vuMsNM8cGt1EOthfnq1ljTC": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "If you have taken a look at the character sheets, you have seen how characters have a series of Traits with different scores. These are the values that define all the things the character can do.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vuMsNM8cGt1EOthfnq1ljTC", "key": "Traits", "name": "Traits", "parent": null, "props": [{"name": "Attributes", "type": "STRING", "value": "The nine Attributes represent Traits that are inherent to the character.", "vk": "scalar"}, {"name": "Skills", "type": "STRING", "value": "These Traits define the knowledge and trained talents of the character.", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "The Disciplines are the mystical powers that the Blood confers to Kindred.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vwv9pIKrKiZ3XGDrKuUdCH3": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "Most Kindred look like regular human beings, only paler, with the rigidity and pale complexion of a corpse. Anyone staring at a vampire long enough will see that there is something wrong with them. However, Kindred have the ability to use their Blood to camouflage themselves.\n\nBy rolling a Rouse Check, a character can make blood flow to their skin, giving them a rosy and healthy appearance. The **Blush of Life** also allows Kindred to interact with touchscreens of smartphones or tablets.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vwv9pIKrKiZ3XGDrKuUdCH3", "key": "Blush of Life", "name": "Blush of Life", "parent": "#vL2Q38sgIJdj6UTRIJyY60v", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vxj9rWo1d1WyJB1jIFghssS": {"aliases": null, "book": "new-blood-reference-guide", "children": [], "choices": [], "desc": "When determining the difficulty of a One-Roll Conflict, determine how strong, qualified or dangerous the opposing side is. Clearly inferior opponents translate into a difficulty of 2. Opponents that are roughly a fair match translate into a difficulty of 4. Clearly more powerful opponents translate into a difficulty of 6.\n\nThis difficulty can then be adjusted based on factors affecting either side. For example, the use of Disciplines or equivalent supernatural might that is unopposed by the other side, or better preparation or positioning, would reduce the overall difficulty by 1.", "entries": [], "enum": null, "file": "vtm5e-0.5-new-blood-reference-guide-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#vxj9rWo1d1WyJB1jIFghssS", "key": "Setting and Adjusting Difficulties for One-roll Conflict", "name": "Setting and Adjusting Difficulties for One-roll Conflict", "parent": "#v93CM43WiAsSKPlwAQLE90W", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}}, "src": "data/new-blood-reference-guide.js"};var T=window.VTM5E=window.VTM5E||{books:{},entities:{},loaded:{}};
T.loaded[d.src]=true;T.books[d.book.id]=d.book;
for(var h in d.entities){T.entities[h]=d.entities[h];}})();
